// W4-L3 · the lesson sheet's inline SVGs (docs/lessons/W4-L3.md), generated by a script from the sheet
// and copied as written, with these changes (each one asserted when the file was generated):
// - figure 2-1: the dashed rails read "正饱和 +7.5 V" / "负饱和约 −8.9 V" (the LM358's light-load swing
//   on ±9 V) instead of a symmetric "±7.5 V 安全裕量";
// - figure 6-1: the two 9 V batteries are the 台式可调直流电源（±9 V）, with red / black / blue leads to
//   the +9 V / GND / −9 V rails; the chip's labels keep light colours on the dark package (values
//   lightSvg leaves alone), the GND rail and Pin 3 wire are ink; developer comments removed;
// - guided mini diagrams: step 2 no longer draws the falling ramp (its sign is the question), step 3
//   no longer draws the second ramp back to 0 V, step 4 no longer prints "−10.0 V" (each is that
//   step's answer).
// All of them are drawn for a dark canvas: `sheet()` recolours them with the shared lightSvg, after
// `tune()` maps the sheet colours lightSvg does not know (scope yellow #facc15, cyan #22d3ee …).

import { lightSvg } from '../../svgTheme';

type Map = Record<string, string>;
const TEXT: Map = { '#facc15': '#a16207', '#eab308': '#a16207', '#22d3ee': '#0e7490', '#fb923c': '#c2410c' };
const FILL: Map = { '#facc15': '#ca8a04', '#eab308': '#ca8a04', '#22d3ee': '#0891b2', '#0b1120': '#fbf7ef', '#14532d': '#dcfce7' };
const STROKE: Map = { '#facc15': '#ca8a04', '#eab308': '#ca8a04', '#22d3ee': '#0891b2' };

/** map the sheet colours lightSvg leaves alone, per role (text / shape fill / stroke) */
export function tune(svg: string): string {
  return svg.replace(/<([a-zA-Z][\w:-]*)(\s[^<>]*?)?(\/?)>/g, (whole, tag: string, attrs: string | undefined, close: string) => {
    if (!attrs) return whole;
    const text = tag === 'text' || tag === 'tspan';
    const a = attrs.replace(/\b(fill|stroke)=(["'])([^"']*)\2/g, (_m, prop: string, q: string, v: string) => {
      const c = v.toLowerCase();
      const m = prop === 'stroke' ? STROKE : text ? TEXT : FILL;
      return `${prop}=${q}${m[c] ?? v}${q}`;
    });
    return `<${tag}${a}${close}>`;
  });
}

export const sheet = (svg: string) => lightSvg(tune(svg));

